installer-gui-script.script:
function reaper_installed() {
  var dirs = ['/Applications'];
  if (system.env.HOME) dirs.push(system.env.HOME + '/Applications');
  for (var i = 0; i < dirs.length; i++) {
    if (system.files.fileExistsAtPath(dirs[i] + '/REAPER.app') || system.files.fileExistsAtPath(dirs[i] + '/REAPER64.app')) return true;
  }
  my.result.type = 'Fatal';
  my.result.title = 'Install REAPER first';
  my.result.message = 'Hibiki runs inside REAPER, and REAPER is not on this Mac yet. Download it from reaper.fm, drag it to Applications, open it once, then open this installer again.';
  return false;
}
